head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[util > M > isEmptyObject]<br/>전달된 객체가 빈 객체({})인지 판별하여 결과를 반환합니다.",
    "validation" : [
        "info(필수) 파라미터로 빈 객체 여부를 검사할 객체를 설정할 수 있어야 합니다.",
        "info 파라미터가 빈 객체({})이면 true 를 반환해야 합니다.",
        "info 파라미터가 빈 객체가 아니면 false 를 반환해야 합니다.",
        "info 파라미터에 null 을 전달하면 false 를 반환해야 합니다.",
    ]
}



scwin.onpageload = function () {
    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



scwin.btn_isEmptyObject_empty_onclick = function () {
    let info = {};
    let ret = WebSquare.util.isEmptyObject(info);
    wf_body_bottom.getObj("scwin").setReturnValue("isEmptyObject({}) : " + ret);
}

scwin.btn_isEmptyObject_notEmpty_onclick = function () {
    let info = {"x": 100};
    let ret = WebSquare.util.isEmptyObject(info);
    wf_body_bottom.getObj("scwin").setReturnValue("isEmptyObject({x: 100}) : " + ret);
}

scwin.btn_isEmptyObject_null_onclick = function () {
    let ret = WebSquare.util.isEmptyObject(null);
    wf_body_bottom.getObj("scwin").setReturnValue("isEmptyObject(null) : " + ret);
}
